package ai.neargo.shop.portal.biz;
import ai.neargo.shop.auth.*;import ai.neargo.shop.common.*;import ai.neargo.shop.member.service.*;import ai.neargo.shop.paybridge.*;import ai.neargo.shop.paybridge.dto.StoredValueScopeViews.*;import ai.neargo.shop.spi.entitlement.*;import java.util.List;import org.springframework.context.annotation.Profile;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@Profile("api") @RestController
public class BizMemberScopeController {
 private final EntitlementScopeResolver authorization;private final ScopedStoredValueMemberService customers;private final MemberService legacy;private final MemberScopeService members;private final MemberScopeQueryService query;
 public BizMemberScopeController(EntitlementScopeResolver authorization,ScopedStoredValueMemberService customers,MemberService legacy,MemberScopeService members,MemberScopeQueryService query){this.authorization=authorization;this.customers=customers;this.legacy=legacy;this.members=members;this.query=query;}
 private String require(String store,boolean recharge){var scope=authorization.resolve(new EntitlementDefinition.RedemptionScope("STORES",List.of(store)));var permitted=BizContext.current().withStore(store);if(!permitted.can(BizPerms.CUSTOMER)||recharge&&!permitted.can(BizPerms.SV_RECHARGE_CREATE))throw BizException.of(ErrorCode.FORBIDDEN);return scope.entityNo();}
 private static EntitlementContext context(){var u=SecurityUtils.requireUser();return new EntitlementContext(u.tenantNo(),u.userNo(),"scoped-member","0".repeat(64));}
 @GetMapping("/biz/stores/{storeNo}/stored-value/customer-candidates") @PreAuthorize("@perm.canBiz('biz:customer') and @perm.canBiz('pay:sv:recharge:create')")
 public Page candidates(@PathVariable String storeNo,@RequestParam(required=false) String keyword,@RequestParam(required=false) String cursor,@RequestParam(defaultValue="20") int size){String entity=require(storeNo,true);return customers.candidates(context(),entity,storeNo,keyword,cursor,size,BizContext.current().withStore(storeNo).can(BizPerms.SV_ACCOUNT_READ));}
 @PostMapping("/biz/stores/{storeNo}/stored-value/customer-selections") @PreAuthorize("@perm.canBiz('biz:customer') and @perm.canBiz('pay:sv:recharge:create')")
 public Selection select(@PathVariable String storeNo,@RequestBody SelectRequest request){String entity=require(storeNo,true);return customers.select(context(),entity,storeNo,request.source(),BizContext.current().withStore(storeNo).can(BizPerms.SV_ACCOUNT_READ));}
 @PostMapping("/biz/stores/{storeNo}/members") @PreAuthorize("@perm.canBiz('biz:customer')")
 public MemberScopeModels.Summary create(@PathVariable String storeNo,@RequestBody MemberCreate request){String entity=require(storeNo,false);var actor=SecurityUtils.requireUser();return ai.neargo.common.data.scope.DataScopeContext.executeWithoutScope(()->{var old=legacy.enroll(entity,request.phone(),request.remark(),request.tagNos(),storeNo,actor.userNo());var member=members.enroll(actor.tenantNo(),entity,storeNo,old.getPersonNo(),actor.userNo(),request.remark());return query.detail(actor.tenantNo(),entity,storeNo,member.scopeMemberNo());});}
}
